              "- Vỗ tay, ghi nhớ.\n- Trả lời: HỌC HÁT BÀI: QUỐC CA VIỆT NAM. Nhạc và lời: Văn Cao.\n- Thực hiện trả lời câu hỏi.\n- Học sinh tự đánh giá và lắng nghe GV nhận xét.\n- Học sinh lắng nghe và ghi nhớ để thực hiện ở nhà."
