          "- Biết cách quan sát và tương tác đơn giản với video trình chiếu nghi lễ chào cờ trên màn hình tivi/máy chiếu. (2.1.CB1a)",
          "- Nhận biết được hình ảnh hoặc video về phong cảnh quê hương đất nước do công cụ AI tạo ra có thể rất đẹp nhưng có thể không hoàn toàn đúng với thực tế địa lý, từ đó biết trân trọng những hình ảnh thực tế hơn. (NLb-B2)",
