            [
              "1. Nhạc cụ Thể hiện các hình tiết tấu bằng nhạc cụ gõ\n* Gõ theo hình tiết tấu:\n- GV trình chiếu hình tiết tấu lên màn hình tivi, nhắc nhở học sinh điều chỉnh tư thế ngồi thẳng lưng, giữ khoảng cách mắt an toàn với màn hình tivi để bảo vệ thị lực. (4.3.CB1a)\n- HD lại cách sử dụng nhạc cụ Maracas.\n- HS quan sát và lắng nghe GV đọc tiết tấu.\n- HS luyện tập tiết tấu, theo hướng dẫn của GV.\n- GV gọi 1 dãy thực hiện tiết tấu.\n- GV HD HS sử dụng lần lượt nhạc cụ Maracas tập vào tiết tấu.",
              "- Điều chỉnh tư thế ngồi ngay ngắn, giữ khoảng cách an toàn với màn hình tivi theo nhắc nhở của GV. (4.3.CB1a)\n- Lắng nghe, ghi nhớ, thực hiện.\n- Theo dõi GV hướng dẫn.\n- HS thực hiện gõ tiết tấu.\n- 1 dãy thực hiện.\n- Tập nhạc cụ Maracas vào hình tiết tấu."
            ],
            [
              "Hoạt động tổ chức, hướng dẫn của GV",
              "Hoạt động học tập của HS"
            ],
            [
              "Kết hợp nhạc cụ gõ theo hình tiết tấu:\n- HD lại cách sử dụng nhạc cụ Maracas.\n- HS quan sát và lắng nghe GV đọc tiết tấu 1.\n- HS luyện tập tiết tấu, theo hướng dẫn của GV.\n- GV HD HS sử dụng lần lượt nhạc cụ Trống con và Maracas tập vào tiết tấu.\n- Chia lớp 2 nhóm, mỗi nhóm gõ 1 nhạc cụ.\n- GV HD HS luyện tập nhạc cụ Temporin và Maracas vào tiết tấu 2 lần lượt như tiết tấu 1 sau đó luyện tập cho thuần thục.\nÔn bài hát Khúc nhạc trên nương xa:\n- GV chia nhóm cho HS luyện tập hát kết hợp gõ đệm.\n- Cặp đôi luyện tập: 1 HS hát, 1 HS gõ đệm.\n- GV tổ chức các hình thức luyện tập phong phú cho HS.",
              "- Lắng nghe, ghi nhớ, thực hiện.\n- Theo dõi GV.\n- HS thực hiện luyện tập.\n- Tập nhạc cụ vào hình tiết tấu.\n- 2 nhóm thực hiện gõ đệm.\n- Thực hiện theo các bước của GV.\n- Thực hiện ôn hát theo nhóm.\n- Các cặp luyện tập phối hợp.\n- Thực hiện theo yêu cầu GV."
            ],
            [
              "Hoạt động tổ chức, hướng dẫn của GV",
              "Hoạt động học tập của HS"
            ],
            [
              "* Hát theo nhóm kết hợp gõ đệm cho bài Khúc nhạc trên nương xa:\n- GV làm mẫu hát kết hợp gõ trống con theo tiết tấu 1 vào bài Khúc nhạc trên nương xa ở 2 câu đầu. Tiết tấu 2 vào 2 câu cuối.\n– GV sử dụng kĩ thuật dạy học “Mảnh ghép” tổ chức hoạt động cho HS:\n+ Nhóm có sở thích về hát sẽ trình bày bài hát với tính chất nhịp nhàng.\n+ Nhóm có sở thích về nhạc cụ sẽ gõ đệm theo phách/ nhịp/ hình tiết tấu đệm cho nhóm hát.\n+ Nhóm có sở thích về vận động cơ thể/ nhịp điệu sẽ cùng phụ hoạ với nhóm nhạc cụ và nhóm hát.\n– GV lấy ngẫu nhiên mỗi nhóm từ 1 đến 2 HS cùng trình bày bài hát Khúc nhạc trên nương xa.\n- Đánh giá và tổng kết tiết học: GV khen ngợi và động viên HS cố gắng, tích cực học tập.\nKhuyến khích HS về nhà hát kết hợp gõ nhạc cụ đệm cho bài hát Khúc nhạc trên nương xa để người thân nghe.\n- Hỏi tên nội dung bài học.\n- Dặn học sinh chuẩn bị bài mới, làm bài tập VBT.",
              "- Theo dõi, lắng nghe, thực hiện.\n- 3 nhóm nghe HD và thực hiện phối hợp.\n- Đại diện các nhóm trình bày trước lớp.\n- Tuyên dương, ghi nhớ, thực hiện.\n- 1 HS trả lời tên bài học.\n- HS ghi nhớ và thực hiện ở nhà."
            ]
