              "– GV cho HS trải nghiệm âm thanh của đàn vi-ô-lông qua trò chơi “Tai ai tinh”.\n– GV chuẩn bị 1 tranh vẽ minh hoạ theo nội dung (SGK trang 38) và cho HS nghe nhạc cụ vi-ô-lông, tem-bơ-rin để HS nhận biết độ cao thấp của âm thanh.\n– GV cho nghe mẫu riêng từ 3 đến 4 lần của từng nhạc cụ và đặt câu hỏi: Em thấy nhạc cụ nào phát ra âm thanh cao hơn và ngược lại?\n– HS nghe 2 nhạc cụ biểu diễn cùng nhau để cảm thụ và phân biệt.\n– GV chuẩn bị 4 câu nhạc bao gồm 2 câu của nhạc cụ vi-ô-lông, 1 câu của nhạc cụ pi-a-nô, 1 câu của nhạc cụ tem-bơ-rin.\n+ GV chuẩn bị phiếu để cả lớp thực hành nghe và phân biệt. GV có thể thực hiện theo mẫu phiếu: Điền V vào đáp án đúng:",
              "- Lắng nghe, ghi nhớ.\n- 3,4 HS phân biệt âm sắc.\n- Trả lời.\n- Lắng nghe, ghi nhớ, phân biệt nhạc cụ.\n- Lắng nghe, ghi nhớ, phân biệt nhạc cụ bằng cách đánh tích."
