              "- Giới thiệu tác giả, tác phẩm:\n+ Nhạc sĩ Bùi Anh Tôn sinh năm 1962 tại Sơn Tây – Hà Nội, quê quán Thành Phố Thái Bình, hiện là chuyên viên phụ trách Bộ môn Âm nhạc thuộc Sở Giáo dục và Đào tạo Thành phố Hồ Chí Minh.\n+ Bài hát Đẹp mãi tuổi thơ là bài hát có sắc thái vui tươi thể hiện thiên nhiên hòa chung vui với các bạn nhỏ đang có 1 tuổi thơ đẹp trong đó có tình bạn thiết tha được sự yêu thương của thầy cô.\n- Hát mẫu song hỏi HS: Em cảm nhận giai điệu của bài hát như thế nào? Lời ca của bài hát nói về những hình ảnh gì?\n- Hướng dẫn HS đọc lời ca theo tiết tấu của bài:\n+ Câu hát 1: Nắng lên rồi ... môi xinh.\n+ Câu hát 2: Gió rung cây ... điệu múa.\n+ Câu hát 3: Tuổi thơ ơi ... muôn khúc ca.\n+ Câu hát 4: Còn mãi mãi ... thiết tha.\n+ Chia câu lời 2 như lời 1.\n- Dạy từng câu nối tiếp:\n+ Câu hát 1 GV đàn giai điệu hát mẫu: Nắng lên rồi ... môi xinh.\n+ Đàn bắt nhịp cả lớp hát lại câu 1.\n+ Câu hát 2 GV đàn giai điệu song đàn lại 1 HS hát theo giai điệu: Gió rung cây ... điệu hát.\n+ Đàn bắt nhịp cả lớp hát lại câu 2.\n+ Đàn câu 1+2 cả lớp hát nhẩm sau đó hát đồng thanh.\n+ Tổ 1 hát lại câu 1+2.\n+ Câu 3,4 và lời 2 dạy như câu 1, 2 khi hát nối câu 3+4 tổ 2 hát.\n- GV cho HS hát nhiều lần cho các em thuộc bài hát. Sửa những lỗi sai cho HS (chú ý hát đúng sắc thái lấy hơi trước các câu, hát rõ lời).",
