              "(- Giới thiệu nước Pháp, tác phẩm:\n+ Pháp tên chính thức là Cộng hòa Pháp là một quốc gia có lãnh thổ chính nằm tại Tây Âu. Một số bài hát lời Việt dân ca Pháp như bài Trời đã sáng rồi, Con chim non...\n+ GV hướng dẫn học sinh sử dụng trình duyệt web trên máy tính giáo viên để tìm kiếm hình ảnh về nước Pháp và tháp Eiffel theo từ khóa gợi ý. (1.1.CB1a)\n+ GV lưu ý học sinh: \"Khi chúng ta sử dụng các công cụ tìm kiếm thông minh hoặc trợ lý AI để tìm hiểu thông tin về nước Pháp, AI có thể đưa ra câu trả lời rất nhanh nhưng đôi khi có thể bị sai lệch hoặc nhầm lẫn. Các em cần đối chiếu lại với sách giáo khoa hoặc hỏi ý kiến thầy cô để kiểm tra lại nhé.\" (NLa.A3)\n+ Bài Con chim non là bài hát có sắc thái nhịp nhàng, tốc độ vừa phải nói về hợp xướng rất hay của những chú chim khi bình minh lên.\n- Hát mẫu song GV đặt câu hỏi: Nghe bài hát em thấy vui không? Bài hát nhanh hay chậm?\n- Hướng dẫn HS đọc lời ca theo tiết tấu của bài:\nCâu hát 1: Bình minh lên có con chim non hoà tiếng hót véo von.\nCâu hát 2: hoà tiếng hót véo von giọng hót vui say sưa.\nCâu hát 3: Này chim ơi hát lên cho vang lời thân ái thiết tha.\nCâu hát 4: rộn vang tới chốn xa càng mến yêu quê nhà.\n+ Dạy từng câu nối tiếp vỗ tay theo phách:\n- Câu hát 1 GV đàn giai điệu hát mẫu: Bình minh lên có con chim non hoà tiếng hót véo von.\n- Đàn bắt nhịp cả lớp hát lại câu 1.\n- Câu hát 2 GV đàn giai điệu song đàn lại 1 HS hát theo giai điệu: Hoà tiếng hót véo von giọng hót vui say sưa.\n- Đàn bắt nhịp cả lớp hát lại câu 2.\n- Đàn câu 1+2 cả lớp hát nhẩm sau đó hát đồng thanh.\n- Tổ 1 hát lại câu 1+2.\n- Câu 3, 4 dạy như câu 1, 2 khi hát nối câu 3+4 tổ 2 hát.\n- GV cho HS hát nhiều lần cho các em thuộc bài hát. Sửa những lỗi sai cho HS. (Lưu ý cho HS vỗ tay hơi mạnh vào phách 1 và vỗ nhẹ ở phách thứ 2, phách thứ 3 để thể hiện sự uyển chuyển, nhịp nhàng của nhịp 3/4).) - Theo dõi, lắng nghe, ghi nhớ.\n- Quan sát GV hướng dẫn tìm kiếm hình ảnh trên internet.\n- Lắng nghe lưu ý về việc kiểm tra thông tin từ AI.\n- Lắng nghe sau đó 1 HS trả lời theo cảm nhận.\n- Đọc lời ca theo hướng dẫn của GV.\n- Lắng nghe.\n- Lớp hát lại câu 1.\n- Lớp lắng nghe, 1 HS hát mẫu.\n- Lớp hát lại câu 2.\n- Lắng nghe, ghi nhớ, thực hiện.\n- Tổ 1 thực hiện.\n- Lắng nghe, ghi nhớ, thực hiện.\n- Lắng nghe những chú ý hát thêm với các hình thức.",
