              "* Nghe và vận động theo nhịp điệu bản nhạc Van-xơ Pha-vô-rít\n– GV hướng dẫn HS vỗ tay theo phách: phách 1 vỗ mạnh, 2 tay vỗ xuống bàn; phách 2, phách 3 vỗ nhẹ nhằm mục đích cho HS cảm thụ về phách mạnh và phách nhẹ trong nhịp 3/4. Khi thực hiện, GV có thể cho HS vỗ tay và đếm số 1 – 2 – 3 cho đều đặn (thực hiện từ 1 đến 2 lần).\n– GV cho HS nghe nhạc và kết hợp vỗ tay theo phách từ 1 – 2 lần.\n– GV hướng dẫn HS nghe nhạc và thực hiện vận động theo hình minh hoạ thực hiện như sau:\n+ Hình 1 sử dụng vào đoạn đầu bản nhạc: Hai HS quay mặt vào nhau và nắm tay nhau nghiêng phải, nghiêng trái vào phách mạnh. Đoạn đầu của bản nhạc Van-xơ Pha-vô-rít thể hiện sự đều đặn, nhịp nhàng của nhịp 3/4. Đây là nét đặc trưng của nhịp valse.\n+ Hình 2 sử dụng vào đoạn giữa bản nhạc: phần đệm có sự thay đổi âm hình đệm tạo nên nét linh hoạt, vui nhộn. Vì vậy, GV có thể hướng dẫn HS vỗ tay sang phải và sang trái theo hình minh hoạ.\n+ GV có thể cho HS nghe nhạc kết hợp vận động cơ thể từ 1 đến 2 lần.",
              "- Theo dõi, thực hiện chậm cùng GV sau đó luyện tập.\n- Thực hiện.\n- Theo dõi, lắng nghe, thực hiện chậm cùng GV sau đó thực hành.\n- Theo dõi, lắng nghe, thực hiện chậm cùng GV sau đó thực hành."
