          "2. Học sinh:",
          "- SGK, vở ghi, nhạc cụ gõ đơn giản.",
          "TIẾT 31: HỌC BÀI HÁT HÈ VỀ VUI QUÁ",
          "Nhạc và Lời: Hoàng Ngọc Oanh",
          "Ngày giảng: 21/4/2026 (3A), 23/4/2026 (3B), 24/4/2026 (3C)"
