              "- Lắng nghe, ghi nhớ cách sử dụng nhạc cụ.\n- Quan sát hình tiết tấu trong SGK và trên màn hình trình chiếu.\n- Đại diện nhóm thực hiện thao tác chạm màn hình máy tính bảng để nghe mẫu tiết tấu chuẩn. (2.1.CB1a)\n- Luyện tập gõ tiết tấu theo hướng dẫn.\n- Các nhóm thực hiện gõ nhạc cụ theo sự phân công.\n- Thực hiện đảo nhạc cụ và luyện tập theo hướng dẫn của GV."
